# hypothesis: len() ignores an annotation-only __len__ and a __getattr__ fallback because special methods are looked up on the type, so len(c) raises TypeError at runtime while a checker that consults __getattr__ might accept it.
from collections.abc import Iterator
from typing import reveal_type


class Base:
    def __iter__(self) -> Iterator[int]:
        yield 1
        yield 2


class Child(Base):
    __len__: int  # annotation only, never a method

    def __getattr__(self, name: str) -> int:
        return 7


def probe() -> None:
    c = Child()
    reveal_type(c.whatever)
    assert c.whatever == 7
    total = 0
    for v in c:
        total += v
    assert total == 3
    try:
        n = len(c)  # expect-error
    except TypeError:
        n = -1
    assert n == -1


probe()
